// Check for leads that need follow-up
// In production, this would query Supabase CRM
// For now, we use a mock database

const now = new Date();
const leadsNeedingFollowUp = [];

// Mock leads database (replace with Supabase query)
const mockLeads = [
  {
    lead_id: 'LEAD-001',
    name: 'Chidi Okonkwo',
    email: 'chidi@example.com',
    phone: '+2348012345678',
    source: 'meta_ads',
    priority: 'hot',
    qualification_status: 'contacted',
    last_followup: new Date(now - 25 * 3600000).toISOString(),
    followup_count: 1,
    max_followups: 5,
    response_received: false,
    next_action: 'follow_up_2'
  },
  {
    lead_id: 'LEAD-002',
    name: 'Aisha Bello',
    email: 'aisha@example.com',
    phone: '+2348098765432',
    source: 'website',
    priority: 'warm',
    qualification_status: 'new',
    last_followup: null,
    followup_count: 0,
    max_followups: 5,
    response_received: false,
    next_action: 'initial_followup'
  },
  {
    lead_id: 'LEAD-003',
    name: 'Emeka Nwosu',
    email: 'emeka@example.com',
    phone: '+2348055512345',
    source: 'referral',
    priority: 'hot',
    qualification_status: 'qualified',
    last_followup: new Date(now - 48 * 3600000).toISOString(),
    followup_count: 2,
    max_followups: 5,
    response_received: false,
    next_action: 'follow_up_3_escalation'
  },
  {
    lead_id: 'LEAD-004',
    name: 'Fatima Abdullahi',
    email: 'fatima@example.com',
    phone: '+2348033344455',
    source: 'whatsapp',
    priority: 'cold',
    qualification_status: 'unqualified',
    last_followup: new Date(now - 72 * 3600000).toISOString(),
    followup_count: 3,
    max_followups: 5,
    response_received: false,
    next_action: 'final_followup'
  }
];

// Filter leads that need follow-up
for (const lead of mockLeads) {
  if (lead.response_received) continue;
  if (lead.followup_count >= lead.max_followups) continue;

  const lastFollowup = lead.last_followup ? new Date(lead.last_followup) : null;
  const hoursSinceLastFollowup = lastFollowup ? (now - lastFollowup) / 3600000 : 999;

  // Determine if follow-up is needed
  let needsFollowUp = false;

  if (lead.followup_count === 0 && hoursSinceLastFollowup > 1) {
    needsFollowUp = true; // Initial follow-up after 1 hour
  } else if (lead.followup_count === 1 && hoursSinceLastFollowup > 24) {
    needsFollowUp = true; // Second follow-up after 24 hours
  } else if (lead.followup_count === 2 && hoursSinceLastFollowup > 48) {
    needsFollowUp = true; // Third follow-up after 48 hours
  } else if (lead.followup_count === 3 && hoursSinceLastFollowup > 72) {
    needsFollowUp = true; // Final follow-up after 72 hours
  }

  if (needsFollowUp) {
    leadsNeedingFollowUp.push({
      ...lead,
      followup_number: lead.followup_count + 1,
      checked_at: now.toISOString()
    });
  }
}

if (leadsNeedingFollowUp.length === 0) {
  return [{ json: { status: 'no_followups_needed', checked_at: now.toISOString(), count: 0 } }];
}

return leadsNeedingFollowUp.map(lead => ({ json: lead }));

// Generate follow-up message based on follow-up number and lead data
const lead = $input.first().json;
const followupNum = lead.followup_number;

let whatsappMessage = '';
let emailSubject = '';
let emailBody = '';
let channel = 'whatsapp';
let urgency = 'normal';

switch (followupNum) {
  case 1:
    // Initial follow-up (1 hour after first contact)
    whatsappMessage = `Hi ${lead.name}! 👋\n\nJust checking in on your enquiry. We noticed you reached out about our services.\n\nDo you have any questions we can answer? We'd love to help you get started.\n\nReference: ${lead.lead_id}`;
    emailSubject = `Following up on your enquiry - ${lead.lead_id}`;
    emailBody = `Hi ${lead.name},<br><br>We wanted to follow up on your recent enquiry. Our team is ready to help you find the right solution.<br><br>Reference: ${lead.lead_id}<br><br>Would you have time for a quick 15-minute call today?<br><br>Best regards,<br>Jules Luxury Team`;
    break;

  case 2:
    // Second follow-up (24 hours)
    whatsappMessage = `Hi ${lead.name}, hope you're well! 😊\n\nWe reached out yesterday about your enquiry. We understand you're busy, so we wanted to make sure you didn't miss us.\n\nIs there a better time for us to connect? You can also reply to this message anytime.\n\nReference: ${lead.lead_id}`;
    emailSubject = `Still here to help - ${lead.lead_id}`;
    emailBody = `Hi ${lead.name},<br><br>Just a friendly reminder about your enquiry. We haven't heard back and wanted to make sure you're all set.<br><br>If your needs have changed, that's perfectly fine too. Just let us know!<br><br>Reference: ${lead.lead_id}<br><br>Cheers,<br>Jules Luxury Team`;
    break;

  case 3:
    // Third follow-up with escalation (48 hours)
    whatsappMessage = `Hi ${lead.name}, last check-in from us! 😊\n\nWe've tried reaching out a couple of times. We don't want to be a bother, so this will be our final follow-up.\n\nIf you'd still like to explore our services, just reply here or click the link below. We'll be here when you're ready.\n\n🔗 [Book a free consultation]\n\nReference: ${lead.lead_id}`;
    emailSubject = `Final follow-up - ${lead.lead_id}`;
    emailBody = `Hi ${lead.name},<br><br>This is our final follow-up regarding your enquiry. We understand priorities change, and that's okay.<br><br>If you'd like to revisit this in the future, we're always here.<br><br>Reference: ${lead.lead_id}<br><br>Warm regards,<br>Jules Luxury Team`;
    urgency = 'low';
    break;

  case 4:
    // Reactivation attempt (72 hours)
    channel = 'email';
    whatsappMessage = null;
    emailSubject = `We'd love to hear from you - ${lead.lead_id}`;
    emailBody = `Hi ${lead.name},<br><br>It's been a few days since your enquiry. We wanted to check in one last time.<br><br>Whether you're ready now or in 6 months, we're here to help when the time is right.<br><br>No pressure at all - just wanted to leave the door open.<br><br>Reference: ${lead.lead_id}<br><br>All the best,<br>Jules Luxury Team`;
    urgency = 'low';
    break;
}

return [{
  json: {
    ...lead,
    followup_channel: channel,
    whatsapp_message: whatsappMessage,
    email_subject: emailSubject,
    email_body: emailBody,
    urgency: urgency,
    followup_generated_at: new Date().toISOString()
  }
}];

// Update lead record with follow-up info
const lead = $input.first().json;

const updatedLead = {
  lead_id: lead.lead_id,
  name: lead.name,
  email: lead.email,
  phone: lead.phone,
  followup_count: lead.followup_number,
  last_followup: new Date().toISOString(),
  last_followup_channel: lead.followup_channel,
  last_followup_message: lead.followup_channel === 'whatsapp' ? lead.whatsapp_message : lead.email_subject,
  next_followup_at: lead.followup_number < lead.max_followups 
    ? new Date(Date.now() + (lead.followup_number * 24 * 3600000)).toISOString()
    : null,
  status: lead.followup_number >= lead.max_followups ? 'dormant' : 'follow_up_sent',
  escalation_needed: lead.followup_number >= 3,
  updated_at: new Date().toISOString()
};

return [{ json: updatedLead }];

// Generate escalation notification for sales manager
const lead = $input.first().json;

if (!lead.escalation_needed) {
  return [{ json: { ...lead, escalation: false } }];
}

const escalation = {
  escalation: true,
  escalation_message: `⚠️ LEAD ESCALATION\n\nLead: ${lead.name} (${lead.lead_id})\nEmail: ${lead.email}\nPhone: ${lead.phone}\nPriority: ${lead.priority}\nFollow-ups sent: ${lead.followup_count}/${lead.max_followups}\n\nThis lead has not responded to ${lead.followup_count} follow-up attempts.\n\nRecommended action: Personal phone call or WhatsApp voice message.`,
  escalation_timestamp: new Date().toISOString()
};

return [{ json: { ...lead, ...escalation } }];

// Final summary
const lead = $input.first().json;

return [{
  json: {
    status: 'completed',
    lead_id: lead.lead_id,
    name: lead.name,
    followup_number: lead.followup_number,
    channel: lead.followup_channel,
    escalation: lead.escalation || false,
    next_followup_at: lead.next_followup_at,
    timestamp: new Date().toISOString()
  }
}];

// No follow-ups needed
return [{
  json: {
    status: 'no_followups_needed',
    message: 'All leads are up to date. No follow-ups required.',
    checked_at: new Date().toISOString()
  }
}];

// Process lead response (when lead replies)
const response = $input.first().json.body;

const result = {
  lead_id: response.lead_id,
  response_type: 'lead_replied',
  response_channel: response.channel || 'whatsapp',
  response_message: response.message || '',
  timestamp: new Date().toISOString(),
  action: 'handoff_to_human',
  priority_boost: true
};

return [{ json: result }];
